from pathlib import Path
import pandas as pd

# Locate the project directory
project_root = Path(__file__).resolve().parents[1]

# Load the dataset generated by feature engineering
file_path = project_root / "data" / "processed" / "matches_with_features.csv"
df = pd.read_csv(file_path)

# Define the features we expect
features = [
    "home_previous_matches",
    "home_avg_goals_scored",
    "home_avg_goals_conceded",
    "away_previous_matches",
    "away_avg_goals_scored",
    "away_avg_goals_conceded"
]

# Display the dataset dimensions
print("Dataset shape:", df.shape)

# Check whether all expected columns exist
missing_columns = [col for col in features if col not in df.columns]

if missing_columns:
    print("Missing feature columns:", missing_columns)
else:
    print("All six historical features are present.")

# Check missing values in the features
print("\nMissing values in each feature:")
print(df[features].isnull().sum())

# Check the target variable
if "result" in df.columns:
    print("\nMatch outcome distribution:")
    print(df["result"].value_counts())
else:
    print("\nERROR: The target column 'result' is missing.")

# Display a sample of the dataset
print("\nFirst five rows:")
print(df.head())